/// index of a player camera state: PlayerCamera+0xb8 + 8 * id holds the state object and the state stores its id; values from data/camerastates.json (render pass).
#[repr(u32)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CameraState {
    /// `FirstPerson`
    FirstPerson = 0,
    /// `AutoVanity`
    AutoVanity = 1,
    /// `VATS`
    VATS = 2,
    /// `Free`
    Free = 3,
    /// `IronSights`
    IronSights = 4,
    /// `Furniture`
    Furniture = 5,
    /// `PlayerCameraTransition`
    PlayerCameraTransition = 6,
    /// `TweenMenu`
    TweenMenu = 7,
    /// `ThirdPersonAlt`
    ThirdPersonAlt = 8,
    /// `ThirdPerson`
    ThirdPerson = 9,
    /// `Horse`
    Horse = 10,
    /// `Bleedout`
    Bleedout = 11,
    /// `Dragon`
    Dragon = 12,
}

impl CameraState {
    #[must_use]
    pub const fn from_u32(value: u32) -> Option<Self> {
        match value {
            0 => Some(Self::FirstPerson),
            1 => Some(Self::AutoVanity),
            2 => Some(Self::VATS),
            3 => Some(Self::Free),
            4 => Some(Self::IronSights),
            5 => Some(Self::Furniture),
            6 => Some(Self::PlayerCameraTransition),
            7 => Some(Self::TweenMenu),
            8 => Some(Self::ThirdPersonAlt),
            9 => Some(Self::ThirdPerson),
            10 => Some(Self::Horse),
            11 => Some(Self::Bleedout),
            12 => Some(Self::Dragon),
            _ => None,
        }
    }
}

/// Named bits of `BSCullingProcess.activePlaneMask` (render pass); unnamed bits pass through `bits`.
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct BSCullingProcess_activePlaneMask(pub u32);

impl BSCullingProcess_activePlaneMask {
    /// testNearPlane (high)
    pub const TEST_NEAR_PLANE: Self = Self(0x1);
    /// testFarPlane (high)
    pub const TEST_FAR_PLANE: Self = Self(0x2);
    /// testLeftPlane (high)
    pub const TEST_LEFT_PLANE: Self = Self(0x4);
    /// testRightPlane (high)
    pub const TEST_RIGHT_PLANE: Self = Self(0x8);
    /// testTopPlane (high)
    pub const TEST_TOP_PLANE: Self = Self(0x10);
    /// testBottomPlane (high)
    pub const TEST_BOTTOM_PLANE: Self = Self(0x20);

    #[must_use]
    pub const fn bits(self) -> u32 {
        self.0
    }

    #[must_use]
    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

